-- Financial literacy (spec 047): the Figma layout of the section, written as ordinary editor markup.
--
-- The site builds its blocks from the page text (headings, quotes, lists, media link paragraphs; see
-- specs/047-financial-literacy/contracts/cms-markup.md), so only page_translations and page_details change and the
-- schema stays as it is. The az text follows Figma; the en text keeps the legacy translation, its new parts are drafts
-- for the editor to check.
--
-- A text is replaced only while it is still the legacy one, recognised by its md5 (research R9): a page an editor has
-- changed is left alone, and a second run changes nothing, since the new text has another hash. Pages are found by
-- their az slug, so a database without them is not touched. The markup is the form the admin editor saves
-- (layout fixtures), so opening and saving a page does not change it.
--
-- "General information" (its text lives on the section root), Seminars, Competitions and the editor's draft copy leave
-- the section's left menu (spec 041). A page_details row that already exists is the editor's choice and stays.

DO $seed$
DECLARE
    updated integer;
BEGIN
    -- In shared environments the tables may belong to another role (see `0028`).
    IF NOT has_table_privilege('page_translations', 'UPDATE')
       OR NOT has_table_privilege('page_details', 'INSERT') THEN
        RAISE WARNING 'spec 047: no UPDATE on page_translations or INSERT on page_details, financial literacy seed skipped';
        RETURN;
    END IF;

    WITH seed (slug, locale, legacy_md5, content) AS (
        VALUES
        ('maliyye-savadliligi', 'az', '6e383b3ce152cbc919085e18662ef3bd', $html$<p>İnsanın fərd kimi inkişafı və uğurunun təməlində sağlamlıq durur. Fiziki və intellektual sağlamlıqla yanaşı, maliyyə sağlamlığı da rasional qərar qəbuletmə üçün əhəmiyyətli faktorlardan biridir. Maliyyə sağlamlığı bütünlükdə cəmiyyət üçün olduqca vacibdir.</p><h2>İnsan maliyyə cəhətdən necə sağlam ola bilər?</h2><p>Bunun üçün artıq kiçik yaşlardan etibarən biz saymağı, hesablamağı, seçim etməyi və qənaətli davranmağı bacarmalıyıq. Bu da sadə maliyyə biliklərinin bünövrəsinin uşaq bağçasından qoyulması zərurətini yaradır.</p><p>Məktəblərdə isə bu biliklər daha da təkmilləşdirilir və möhkəmləndirilir. Məktəblilər sadə büdcə planlaması bacarıqlarına yiyələnirlər və bu biliklər ailə üzvlərinin maliyyə qərarlarına arzuolunan töhfə olur.</p><h2>Maliyyə savadlılığı nədir?</h2><blockquote><p>Maliyyə savadlılığı fərdlərin maliyyə məhsul və xidmətlərini başa düşmək, maliyyə risk və imkanlarını qiymətləndirmək, rasional seçimlər etmək üçün zəruri olan məlumatlılıq səviyyəsi, bilik, bacarıq və davranışlar toplusudur.</p><p>İƏİT (İqtisadi Əməkdaşlıq və İnkişaf Təşkilatı), 2012</p></blockquote><p>Maliyyə savadlılığını insanlar həyatları boyu qazandıqları üçün bu istiqamətdə inkişaf məktəb təhsili ilə məhdudlaşmır. Fərdlər tələbə, işçi, menecer və ya ailə başçısı kimi daim maliyyə qərarları verməli olurlar. Təbii ki, maliyyə savadlılığı yüksək olan insanlar bu qərarların öhdəsindən asanlıqla gəlir.</p><h2>Maliyyə sağlamlığının dörd prinsipi</h2><p>Yüksək rifah üçün aşağıdakı vərdiş və bacarıqlar maliyyə savadlılığının yüksək olduğunu göstərən faktorlardır:</p><ul><li><p><strong>Dayanıqlı gəlir</strong></p><p>Sabit və davamlı gəlir mənbəyinə malik olmaq</p></li><li><p><strong>Səmərəli xərcləmə</strong></p><p>Xərcləri planlaşdırmaq və büdcəyə nəzarət etmək</p></li><li><p><strong>Effektiv qənaət</strong></p><p>Gələcək və gözlənilməz hallar üçün yığım etmək</p></li><li><p><strong>Rasional sərmayə</strong></p><p>Risk və gəlirliliyi qiymətləndirərək investisiya etmək</p></li></ul><p>Təcrübə göstərir ki, maliyyə sağlamlığının bu dörd vacib prinsipinə əməl edən istehlakçılar hətta tarixin böyük böhranlarından belə üzü ağ çıxa bilmişdilər.</p><h2>Mərkəzi Bankın fəaliyyəti</h2><p>Azərbaycan Respublikasının Mərkəzi Bankı istehlakçıların maliyyə savadlılığının artırılması və bu yolla onların hüquqlarının müdafiəsi fonunda müxtəlif səpkili tədbirlər həyata keçirir.</p><h3>Əsas hədəf qrupları</h3><ul><li><p>Məktəblilər</p></li><li><p>Tələbələr</p></li><li><p>Müəllimlər</p></li><li><p>Ev təsərrüfatı ilə məşğul olan yaşlı əhali</p></li><li><p>Kiçik və orta sahibkarlar</p></li><li><p>İnsan resursları menecerləri</p></li><li><p>İqtisadiyyat və bankçılıq üzrə jurnalistlər</p></li></ul><h3>Maarifləndirmə formatları</h3><p>Maarifləndirmə məqsədilə qeyd olunan hədəf qruplarına təlim və seminarlar, yay məktəbləri, iş yerlərində tədbirlər təşkil edilir. Bu çərçivədə ictimai aksiyalar, müxtəlif nominasiyalarda müsabiqələr, təbliğat-təşviqat kampaniyaları həyata keçirilmiş, habelə praktiki əhəmiyyəti olan maarfləndirici oyunlar və müxtəlif intellektual resurslar yaradılmışdır.</p><p><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1380" data-media-link="">1</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1381" data-media-link="">2</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1382" data-media-link="">3</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1383" data-media-link="">4</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1384" data-media-link="">5</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1385" data-media-link="">6</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1386" data-media-link="">7</a></p><blockquote><p>Sizi də bu təşəbbüslərə qoşulmağa dəvət edirik!</p><p>Maliyyə sağlamlığınızın qayğısına birlikdə qalaq!</p><p>Müraciət, təklif və rəylər üçün ünvan: <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:mmpi@cbar.az">mmpi@cbar.az</a></p></blockquote>$html$),
        ('maliyye-savadliligi', 'en', '056c6e76ace0b74c578500a90f808272', $html$<p>Health is the foundation of a person's development and success. Along with physical and intellectual health, financial health is an essential component of rational decision-making. Financial health is crucial for the well-being of society as a whole.</p><h2>What does it mean to be financially healthy?</h2><p>In order to accomplish this, we must be able to count, calculate, make choices, and act frugally from a young age. Therefore, it is necessary to establish a foundation of basic financial knowledge in kindergarten.</p><p>This knowledge is further refined and reinforced in schools. Students learn basic budget planning, which becomes a valuable asset when making financial decisions with family members.</p><h2>What is financial literacy?</h2><blockquote><p>Financial literacy is a set of awareness, knowledge, skills, attitudes and behaviours that enable individuals to understand financial products and services, assess financial risks and opportunities, and make rational choices.</p><p>OECD (Organisation for Economic Co-operation and Development), 2012</p></blockquote><p>Since financial literacy is acquired throughout one's lifetime, its development is not limited to school education. People constantly have to make financial decisions as students, employees, managers, and heads of households. Naturally, people with high financial literacy cope with these decisions easily.</p><h2>Four principles of financial health</h2><p>The following habits and skills indicate high financial literacy and lead to greater well-being:</p><ul><li><p><strong>Stable income</strong></p><p>Having a steady and sustainable source of income</p></li><li><p><strong>Efficient spending</strong></p><p>Planning expenses and keeping to a budget</p></li><li><p><strong>Effective saving</strong></p><p>Saving for the future and for the unexpected</p></li><li><p><strong>Rational investment</strong></p><p>Investing after weighing risk and return</p></li></ul><p>Experience shows that consumers who followed the four essential principles of financial health were able to survive even the greatest crises in history unscathed.</p><h2>Activities of the Central Bank</h2><p>The Central Bank of the Republic of Azerbaijan is implementing various measures to increase consumers' financial literacy and thereby protect their rights.</p><h3>Main target groups</h3><ul><li><p>Schoolchildren</p></li><li><p>Students</p></li><li><p>Teachers</p></li><li><p>Elderly people engaged in household work</p></li><li><p>Small and medium-sized entrepreneurs</p></li><li><p>Human resource managers</p></li><li><p>Journalists specialising in economics and banking</p></li></ul><h3>Awareness formats</h3><p>To raise awareness, trainings, seminars, summer schools, and workplace events are organized for the aforementioned target groups. In this context, public actions, competitions in various categories, and propaganda campaigns have been carried out. Educational games of practical importance and various intellectual resources have also been created.</p><p><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1380" data-media-link="">1</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1381" data-media-link="">2</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1382" data-media-link="">3</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1383" data-media-link="">4</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1384" data-media-link="">5</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1385" data-media-link="">6</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1386" data-media-link="">7</a></p><blockquote><p>Join us in supporting these initiatives!</p><p>Let's take care of our financial health together!</p><p>For inquiries, suggestions, and comments, please contact us at: <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:mmpi@cbar.az">mmpi@cbar.az</a></p></blockquote>$html$),
        ('maliyye-savadliligi-portali', 'az', '5b5e10f6a600c0ec257feca4d0bee0d3', $html$<p>“Maliyyə savadlılığı” portalı (<a target="_blank" rel="noopener noreferrer nofollow" href="http://www.bizimpullar.az">www.bizimpullar.az</a>) 2015-ci il tarixindən istifadəyə verilmişdir.</p><p>Portalın əsas məqsədi maliyyə savadlılığının artırılması istiqamətində bütün təşəbbüsləri (resurslar, tədbirlər haqqında məlumatlar və s.) vahid bir virtual məkanda toplamaq, eyni zamanda ölkədə maliyyə savadlılığı üzrə əsas təşviqedici platforma olmaqdır.</p><blockquote><p>Portalın resurslarından istifadə hər kəs üçün əlçatandır və heç bir qeydiyyat tələb olunmur.</p></blockquote><p><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1387" data-media-link="">1</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1388" data-media-link="">2</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1389" data-media-link="">3</a></p><h2>Maliyyə xidmətləri</h2><p>Portalın əsas resurslarının izah edilməsi məqsədilə müxtəlif mövzuları əhatə edən məlumat xarakterli videoçarxlar (animasiyalar) hazırlanmışdır. Müasir auditoriya, xüsusi ilə də gənclər, mütaliədən daha çox səsli və vizual materiallara üstünlük verirlər. Bu məqsədlə vacib maliyyə və bank anlayışları haqqında məlumatlar geniş əhali qruplarına daha əlçatan və aydın formada təqdim edilir. Burada "Kredit nədir?", "Əmanət nədir?", "Təmassız kartlar" kimi bir sıra mövzulara yer verilmiş, əhatə olunan mövzular "bir sual-bir cavab" prinsipi üzərində qurulmuşdur. Bütün bu mövzular portalın "Maliyyə xidmətləri" bölməsində istifadəçilərə təqdim olunur.</p><h2>Mərkəzi Bank</h2><p>Geniş yayılmış maliyyə və bank anlayışlarından əlavə "Siyasət faiz dərəcəsi", "Tədiyyə balansı", "İnflyasiya" kimi mürəkkəb makro-iqtisadi anlayışlar da bu portalda sadə dillə izah olunmuşdur. Bu istiqamətdəki mövzular portalın Mərkəzi Bank bölməsində yerləşdirilmişdir.</p><h2>Pullar</h2><p>"Pullar" bölməsində dövriyyədə olan yenilənmiş kağız pullar haqqında animasiyalar yerləşdirilmişdir. Burada hər bir nominalın üzərində yerləşən təsvirlər, mühafizə elementləri haqqında maraqlı və maarifləndirici məlumatlar videorolik formatında təqdim olunmuşdur.</p><h2>“Mərkəzi Bank” oyun simulyatoru</h2><p>Animasiyalardan başqa portalda praktiki əhəmiyyəti olan oyunlara da yer verilmişdir. Onlar arasında "Mərkəzi Bank" oyun simulyatoru istifadəçilərin xüsusi rəğbətini qazanmışdır. Bu alət istifadəçiyə Mərkəzi Bankın iqtisadiyyatda əsas rolunu dərk etməyə kömək edir. Oyun iştirakçısı Mərkəzi Bankın rolunu yerinə yetirməklə, əsas pul siyasəti aləti olan uçot faiz dərəcəsini idarə edərək iqtisadi artım və inflyasiyanın səviyyələrini müəyyən bir intervalda saxlamalıdır. Daha maraqlı və reallığa uyğun olması üçün oyun simulyasiyasında bir neçə iqtisadi şoklar nəzərdə tutulmuşdur.</p><h2>Xəbərlər</h2><p>Maliyyə savadlılığı istiqamətində həyata keçirilən tədbirlər, seminarlar, müsabiqələr, yeni resursların yaradılması kimi bir sıra məsələlər haqqında informasiyalar "Xəbərlər" bölməsində yerləşdirilmişdir.</p><h2>Digər bölmələr</h2><p>Əlavə olaraq portalın digər bölmələrindən də (virtual muzey, təhsil, kalkulyatorlar və s.) maraqlı və faydalı məlumatlar əldə etmək mümkündür.</p><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.bizimpullar.az/">Portala keçid: www.bizimpullar.az</a></p>$html$),
        ('maliyye-savadliligi-portali', 'en', 'e316fb18301cb570ff5eaddebb3241cb', $html$<p>The Financial Literacy portal (<a target="_blank" rel="noopener noreferrer nofollow" href="http://www.bizimpullar.az">www.bizimpullar.az</a>) has been in use since 2015.</p><p>The portal's main goal is to bring together all initiatives aimed at increasing financial literacy, such as resources and information about events, in one virtual space. At the same time, it aims to become the country's main promotional platform for financial literacy.</p><blockquote><p>Everyone can access the portal's resources, and registration is not required.</p></blockquote><p><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1387" data-media-link="">1</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1388" data-media-link="">2</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1389" data-media-link="">3</a></p><h2>Financial services</h2><p>To explain the main features of the portal, we have prepared informative videos (animations) that cover various topics. The modern audience, especially young people, prefers audio-visual materials to reading. These videos present important financial and banking concepts in a clear and accessible way to a wide range of population groups. Topics include "What is a loan?", "What is a deposit?", and "Contactless cards." Each topic follows the principle of "one question — one answer." These topics are presented to users in the "Financial Services" section of the portal.</p><h2>Central Bank</h2><p>In addition to common financial and banking concepts, this portal also explains complex macroeconomic concepts such as "policy interest rate," "balance of payments," and "inflation" in simple language. These topics are posted in the Central Bank section of the portal.</p><h2>Money</h2><p>The "Money" section contains animations about updated paper money in circulation. It presents interesting and educational information about the images and security features on each denomination in video format.</p><h2>"Central Bank" game simulator</h2><p>In addition to animations, the portal includes practical games. The "Central Bank" game simulator, in particular, has gained special popularity among users. This tool helps users understand the Central Bank's main role in the economy. Playing the role of the Central Bank, the game participant must maintain economic growth and inflation levels within a certain range by controlling the refinancing rate, a key monetary policy instrument. Several economic shocks are provided to make the game simulation more interesting and realistic.</p><h2>News</h2><p>The "News" section contains information on various topics, including events, seminars, competitions, and the development of new financial literacy resources.</p><h2>Other sections</h2><p>Additionally, you can find interesting and useful information in other sections of the portal, such as the virtual museum, education, and calculators.</p><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.bizimpullar.az/">Go to the portal: www.bizimpullar.az</a></p>$html$),
        ('virtual-tehsil-platformasi', 'az', 'e9f452f576a0f95f6057e0a9bf5ea8fe', $html$<p>Azərbaycan Respublikasının Mərkəzi Bankının Virtual Təhsil Platforması – <a target="_blank" rel="noopener noreferrer nofollow" href="https://edu.e-cbar.az/">https://edu.e-cbar.az/</a> 2017-ci ildə fəaliyyətə başlamışdır.</p><p>Ənənəvi təlim üsullarını müasir formatda təklif edən bu platformanın əsas məqsədi iqtisadiyyat və maliyyə-bank sektorunda çalışan, bu istiqamətdə təhsil alan, həmçinin öz bilik və bacarığını inkişaf etdirmək istəyən şəxslərə, o cümlədən şagirdlərə dəstək olmaqdır.</p><blockquote><p>Platformada yerləşdirilən bütün resurslar ödənişsizdir.</p></blockquote><p><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1390" data-media-link="">1</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1391" data-media-link="">2</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1392" data-media-link="">3</a></p><h2>Distant tədris modulları</h2><p>Platformada mövcud olan distant tədris modulları istifadəçilərə zaman və məkan fərqi olmadan peşəkarlıq səviyyəsini təkmilləşdirmək imkanı yaradır.</p><p>Kursların hazır və virtual mühitdə yerləşdirilməsi iştirakçılara daha rahat və sərbəst təhsil almaq imkanı yaradır. Bu, həmçinin istifadəçilərin üçüncü şəxslərdən (müəllim, qrup yoldaşı, inzibatçı) asılılığını azaldaraq keyfiyyətli tədris şəraiti ilə təmin edir. İştirakçılar ehtiyac və istəyindən asılı olaraq istənilən vaxt portala daxil ola bilər.</p><h2>Qeydiyyat</h2><p>Tədris prosesinin effektivliyini izləmək məqsədilə platformada iştirakçıların qeydiyyatı zəruridir. Qeydiyyat haqqında ətraflı məlumatı bu link vasitəsilə əldə etmək olar: <a target="_blank" rel="noopener noreferrer nofollow" href="https://youtu.be/0iNZkyQ0Q7M">https://youtu.be/0iNZkyQ0Q7M</a></p><h2>Sertifikat</h2><p>Kursu tamamlayaraq yekun imtahanda uğurlu nəticə əldə edən iştirakçılara sertifikat təqdim olunur. Lakin, təcrübə göstərir ki, iştirakçıların əksəriyyəti təkcə sertifikat almaqda deyil, həm də özünü inkişaf etdirməkdə maraqlıdırlar.</p><p>Platforma iştirakçılarının rəyləri ilə qeyd edilmiş linkdən istifadə edərək tanış ola bilərsiniz: <a target="_blank" rel="noopener noreferrer nofollow" href="https://youtu.be/0MuSg4qVLMc">https://youtu.be/0MuSg4qVLMc</a></p><h2>Uşaqlar üçün kurslar</h2><p>Hədəf auditoriyasının ehtiyaclarını nəzərə almaqla son illərdə platformada uşaqlar üçün də maliyyə savadlılığı mövzusunda kurslar açılmışdır. Əminik ki, hər bir valideyn öz övladının maliyyə savadlılığının artırılmasında maraqlıdır. Bu istiqamətdə "Uşaqlar və pullar" kursunu baza kurs olaraq bütün valideynlərə təklif edirik. Uşaqların asudə vaxtlarında bu kursu dinləmələri və başa çatdırmaları üçün valideyinlər tərəfindən lazımi şəraitin yaradılması zəruridir. Xüsusilə qeyd etmək istəyirik ki, bu kurs üç dildə (Azərbaycan, rus və ingilis dilləri) təklif olunur.</p><h2>Əlaqə</h2><p>Müraciət, rəy və dəstək üçün ünvan: <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:edu@cbar.az">edu@cbar.az</a></p><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://edu.e-cbar.az/">Platformaya keçid: edu.e-cbar.az</a></p>$html$),
        ('virtual-tehsil-platformasi', 'en', '910bcce9667d82db15230275dec7d262', $html$<p>The Virtual Education Platform of the Central Bank of the Republic of Azerbaijan – <a target="_blank" rel="noopener noreferrer nofollow" href="https://edu.e-cbar.az/">https://edu.e-cbar.az/</a> started operating in 2017.</p><p>The main goal of this platform is to support individuals, including students and professionals working in the economy and finance-banking sectors, who want to develop their knowledge and skills in this field. The platform offers traditional training methods in a modern format.</p><blockquote><p>All resources posted on the platform are free of charge.</p></blockquote><p><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1390" data-media-link="">1</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1391" data-media-link="">2</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1392" data-media-link="">3</a></p><h2>Distance learning modules</h2><p>The distance learning modules on the platform allow users to advance professionally regardless of time or place.</p><p>Placing courses in a ready-made, virtual environment provides participants with a more comfortable, free education. It also reduces their dependence on third parties, such as teachers, groupmates, and administrators, and provides them with quality learning conditions. Participants can access the portal at any time, depending on their needs and desires.</p><h2>Registration</h2><p>To monitor the effectiveness of the educational process, participants must register on the platform. More information about registration can be found at this link: <a target="_blank" rel="noopener noreferrer nofollow" href="https://youtu.be/0iNZkyQ0Q7M">https://youtu.be/0iNZkyQ0Q7M</a></p><h2>Certificate</h2><p>Participants who successfully complete the course and pass the final exam will be awarded a certificate. However, experience shows that participants are interested not only in receiving a certificate, but also in self-development.</p><p>You can read the platform participants' opinions using the provided link: <a target="_blank" rel="noopener noreferrer nofollow" href="https://youtu.be/0MuSg4qVLMc">https://youtu.be/0MuSg4qVLMc</a></p><h2>Courses for children</h2><p>In recent years, courses on financial literacy have been added to the platform for children, taking into account the needs of the target audience. We believe that all parents are interested in improving their children's financial literacy. To that end, we offer the "Children and Money" course to all parents as a basic introduction. Parents must create the conditions that allow their children to listen to and complete this course in their free time. We would especially like to note that this course is offered in three languages (Azerbaijani, Russian, and English).</p><h2>Contact</h2><p>For inquiries, feedback and support, please contact: <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:edu@cbar.az">edu@cbar.az</a></p><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://edu.e-cbar.az/">Go to the platform: edu.e-cbar.az</a></p>$html$),
        ('maliyye-mehsul-ve-xidmetlerinin-melumat-axtaris-sistemi', 'az', '19fca6a8fb68a11470f377c286e258c8', $html$<p>Əhalinin maliyyə xidmətlərinə çıxış imkanlarının asanlaşdırılması və bu xidmətlərdən istifadənin stimullaşdırılması məqsədilə 2019-cu ildən etibarən "Maliyyə məhsul və xidmətlərinin məlumat-axtarış sistemi" - <a target="_blank" rel="noopener noreferrer nofollow" href="https://infobank.az/">https://infobank.az/</a> - istifadəyə verilmişdir.</p><p>Sistem eyni zamanda, maliyyə xidmətləri bazarında rəqabəti gücləndirmək, təqdim olunan məhsul və xidmətlərin keyfiyyətini artırmaq məqsədi də daşıyır.</p><blockquote><p>Sistemdəki məlumatlar mütəmadi olaraq monitorinq olunur, yenilənir və zənginləşdirilir.</p></blockquote><p><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1393" data-media-link="">1</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1394" data-media-link="">2</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1395" data-media-link="">3</a></p><h2>Necə işləyir</h2><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://infobank.az/">https://infobank.az/</a> tələb olunan məlumatı maksimum bir dəqiqə ərzində əldə etməyə imkan yaradır. Burada istehlakçıların maliyyə davranışlarına xidmət edəcək faydalı və lazımi məlumatlar vahid bir məkanda toplanmışdır. Xüsusi qeyd etmək lazımdır ki, axtarış bazarda mövcud və aktual olan bütün maliyyə xidmətlərinə dair təkliflər əsasında aparılır.</p><h2>Əlaqə</h2><p>Rəy, təklif və dəstək üçün ünvan: <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:infobank@cbar.az">infobank@cbar.az</a></p><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://infobank.az/">Sistemə keçid: infobank.az</a></p>$html$),
        ('maliyye-mehsul-ve-xidmetlerinin-melumat-axtaris-sistemi', 'en', '1926d220609495b2c1f6ef391940318b', $html$<p>To facilitate access to financial services and encourage their use, the "Information and Search System for Financial Products and Services" (<a target="_blank" rel="noopener noreferrer nofollow" href="https://infobank.az/">https://infobank.az/</a>) has been launched since 2019.</p><p>The system also aims to strengthen competition in the financial services market and improve the quality of products and services.</p><blockquote><p>The system's information is regularly monitored, updated, and enriched.</p></blockquote><p><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1393" data-media-link="">1</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1394" data-media-link="">2</a><a target="_blank" rel="noopener noreferrer nofollow" href="/media/1395" data-media-link="">3</a></p><h2>How it works</h2><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://infobank.az/">https://infobank.az/</a> allows you to access the information you need within a maximum of one minute. Useful and necessary information about consumer financial behavior is collected in one place here. Note that the search is based on all available and relevant financial services on the market.</p><h2>Contact</h2><p>For feedback, suggestions and support, please contact: <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:infobank@cbar.az">infobank@cbar.az</a></p><p><a target="_blank" rel="noopener noreferrer nofollow" href="https://infobank.az/">Go to the system: infobank.az</a></p>$html$)
    ),
    target AS (
        SELECT az.page_id, s.locale, s.legacy_md5, s.content
        FROM seed s
        JOIN page_translations az ON az.locale = 'az' AND az.slug = s.slug
    )
    UPDATE page_translations t
    SET content = target.content
    FROM target
    WHERE t.page_id = target.page_id
      AND t.locale = target.locale
      AND md5(t.content) = target.legacy_md5;
    GET DIAGNOSTICS updated = ROW_COUNT;
    RAISE NOTICE 'spec 047: % financial literacy texts written', updated;

    INSERT INTO page_details (page_id, show_in_side_nav)
    SELECT t.page_id, false
    FROM page_translations t
    WHERE t.locale = 'az'
      AND t.slug IN ('umumi-melumat', 'seminarlar-vebinarlar', 'musabiqeler', 'maliyye-savadliligi-copy')
    ON CONFLICT (page_id) DO NOTHING;
END
$seed$;
